/// 从各模块源码提取的「参数改名 + 默认值」。
/// 透传 query 无法覆盖这些差异（例如 mv/url 的 r:1080、search 的 s←keywords）。
pub fn apply_spec(identifier: &str, data: &mut serde_json::Map<String, serde_json::Value>) {
    match identifier {
        "daily_signin" => {
            data.entry("type").or_insert(serde_json::json!(0));
        }
        "listen_data_realtime_report" => {
            data.entry("type").or_insert(serde_json::json!("week"));
        }
        "listen_data_report" => {
            data.entry("type").or_insert(serde_json::json!("week"));
        }
        "listen_data_song_play_rank" => {
            data.entry("type").or_insert(serde_json::json!("month"));
        }
        "mv_detail" => {
            if let Some(value) = data.remove("mvid") {
                data.insert("id".to_string(), value);
            }
        }
        "mv_url" => {
            data.entry("r").or_insert(serde_json::json!(1080));
        }
        "playlist_create" => {
            data.entry("privacy").or_insert(serde_json::json!(0));
            data.entry("type").or_insert(serde_json::json!("NORMAL"));
        }
        "playlist_subscribers" => {
            data.entry("limit").or_insert(serde_json::json!(20));
            data.entry("offset").or_insert(serde_json::json!(0));
        }
        "record_recent_song" => {
            data.entry("limit").or_insert(serde_json::json!(100));
        }
        "search_multimatch" => {
            if let Some(value) = data.remove("keywords") {
                data.insert("s".to_string(), value);
            }
            data.entry("type").or_insert(serde_json::json!(1));
            data.entry("s").or_insert(serde_json::json!(""));
        }
        "simi_artist" => {
            if let Some(value) = data.remove("id") {
                data.insert("artistid".to_string(), value);
            }
        }
        "song_dynamic_cover" => {
            if let Some(value) = data.remove("id") {
                data.insert("songId".to_string(), value);
            }
        }
        "song_red_count" => {
            if let Some(value) = data.remove("id") {
                data.insert("songId".to_string(), value);
            }
        }
        "song_wiki_summary" => {
            if let Some(value) = data.remove("id") {
                data.insert("songId".to_string(), value);
            }
        }
        "ugc_album_get" => {
            if let Some(value) = data.remove("id") {
                data.insert("albumId".to_string(), value);
            }
        }
        "ugc_artist_get" => {
            if let Some(value) = data.remove("id") {
                data.insert("artistId".to_string(), value);
            }
        }
        "ugc_song_get" => {
            if let Some(value) = data.remove("id") {
                data.insert("songId".to_string(), value);
            }
        }
        "user_record" => {
            data.entry("type").or_insert(serde_json::json!(0));
        }
        "vip_info" => {
            if let Some(value) = data.remove("uid") {
                data.insert("userId".to_string(), value);
            }
            data.entry("userId").or_insert(serde_json::json!(""));
        }
        _ => {}
    }
}

